FuncDef.Code:
float opSmoothInfRepeatXZ(inout vec3 p, float spacingX, float spacingZ, float smoothnessX, float smoothnessZ)
{
    vec2 spacing    = vec2(spacingX, spacingZ);
    vec2 smoothness = vec2(smoothnessX, smoothnessZ);
    vec2 halfsize = spacing*0.5;
    vec2 c = floor((p.xz + halfsize)/spacing);
    float cellIndex = c.x + c.y + PI * sin(c.x * c.y);
    p.xz = modEx(p.xz + halfsize, spacing, smoothness) - halfsize;

    return cellIndex;
}
